// Pull the topic and chat id out of the Telegram message.
const msg = $input.first().json.message || {};
const chatId = msg.chat && msg.chat.id;
const topic = (msg.text || '').replace(/^\/\w+(@\w+)?\s*/, '').trim();

if (!chatId || !topic) {
  // Nothing usable (sticker, photo, bare /start): stop this run quietly.
  return [];
}

return [{ json: { chatId, topic } }];

// Turn Tavily results into a prompt for the script writer.
const { chatId, topic } = $('Extract topic').first().json;
const results = ($input.first().json.results || []).slice(0, 5);

const sources = results.map((r) => ({ title: r.title, url: r.url }));
const research = results.length
  ? results
      .map((r, i) => `${i + 1}. ${r.title}\n${(r.content || '').slice(0, 500)}`)
      .join('\n\n')
  : 'No recent coverage found. Write from general knowledge and do not invent news.';

const system = [
  'You write scripts for short vertical videos (TikTok, YouTube Shorts, Instagram Reels).',
  'Use only facts supported by the research notes. Do not invent statistics, quotes or events.',
  'Reply with a single JSON object and nothing else, with these keys:',
  '"title" (max 60 characters),',
  '"hook" (one spoken sentence for the first 3 seconds),',
  '"script" (the full voiceover including the hook, 90 to 130 words, plain spoken text, no stage directions, no emojis),',
  '"caption" (one or two sentences for the post),',
  '"hashtags" (array of 5 strings, each starting with #).',
].join(' ');

const user = `Topic: ${topic}\n\nResearch notes from the last week:\n\n${research}`;

return [
  {
    json: {
      chatId,
      topic,
      sources,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    },
  },
];

// Read the model's JSON reply and build the Telegram message.
const { chatId, topic, sources } = $('Build prompt').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '';

let data;
try {
  data = JSON.parse(raw);
} catch (err) {
  // The model ignored the JSON instruction: fall back to using its text as the script.
  data = { title: topic, hook: '', script: raw, caption: '', hashtags: [] };
}

const script = String(data.script || '').trim();
if (!script) {
  throw new Error('The model returned an empty script.');
}

const esc = (s) =>
  String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hashtags = Array.isArray(data.hashtags) ? data.hashtags.join(' ') : '';

const parts = [
  `<b>${esc(data.title || topic)}</b>`,
  data.hook ? `<b>Hook:</b> ${esc(data.hook)}` : '',
  `<b>Script:</b>\n${esc(script)}`,
  data.caption ? `<b>Caption:</b> ${esc(data.caption)}` : '',
  hashtags ? esc(hashtags) : '',
  sources.length
    ? '<b>Sources:</b>\n' + sources.map((s) => `- ${esc(s.title)}\n  ${esc(s.url)}`).join('\n')
    : '',
].filter(Boolean);

// Telegram rejects messages over 4096 characters.
const message = parts.join('\n\n').slice(0, 4000);

return [{ json: { chatId, topic, title: data.title || topic, script, message } }];
